// Local Natural Language Parser for CareCircle Smart Assistant (Alexa+ Simulation)
// Runs entirely on the client using rule-based heuristic parsing without external APIs or cloud models.

import { generateStableTaskId } from "./storage.js";

const LOCAL_ENGINE_NOTICE =
  "Generated by CareCircle Local Heuristic Engine (rule-based pattern matching, no external AI model).";

/**
 * Resolves natural language date references to YYYY-MM-DD
 */
export function parseDate(text) {
  if (!text) return null;
  const lower = text.toLowerCase();
  const now = new Date();

  if (lower.includes("tomorrow")) {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    return d.toISOString().split("T")[0];
  }

  if (lower.includes("today") || lower.includes("tonight")) {
    return now.toISOString().split("T")[0];
  }

  if (lower.includes("day after tomorrow")) {
    const d = new Date();
    d.setDate(d.getDate() + 2);
    return d.toISOString().split("T")[0];
  }

  // Days of week: "next monday", "this friday", "on friday"
  const days = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  for (let i = 0; i < days.length; i++) {
    const dayName = days[i];
    if (lower.includes(dayName)) {
      const currentDay = now.getDay();
      let diff = i - currentDay;
      if (diff <= 0 || lower.includes(`next ${dayName}`)) {
        diff += 7;
      }
      const d = new Date();
      d.setDate(d.getDate() + diff);
      return d.toISOString().split("T")[0];
    }
  }

  // Explicit date match like 2026-10-25 or 2026/10/25
  const isoMatch = text.match(/\b(20\d\d[-/]\d{1,2}[-/]\d{1,2})\b/);
  if (isoMatch) {
    return isoMatch[1].replace(/\//g, "-");
  }

  return null;
}

/**
 * Resolves natural language time references to HH:MM (24-hour format)
 */
export function parseTime(text) {
  if (!text) return null;
  const lower = text.toLowerCase();

  if (lower.includes("noon")) return "12:00";
  if (lower.includes("midnight")) return "00:00";
  if (lower.includes("morning")) return "09:00";
  if (lower.includes("evening")) return "18:00";
  if (lower.includes("afternoon")) return "14:00";

  // Regex matches: "5 PM", "5:30 pm", "5pm", "17:00", "9:45 AM"
  const time12Match = text.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);
  if (time12Match) {
    let hour = parseInt(time12Match[1], 10);
    const minute = time12Match[2] ? time12Match[2].padStart(2, "0") : "00";
    const meridiem = time12Match[3].toLowerCase();

    if (meridiem === "pm" && hour < 12) {
      hour += 12;
    } else if (meridiem === "am" && hour === 12) {
      hour = 0;
    }
    return `${String(hour).padStart(2, "0")}:${minute}`;
  }

  // 24-hour regex: "17:00"
  const time24Match = text.match(/\b([01]?\d|2[0-3]):([0-5]\d)\b/);
  if (time24Match) {
    return `${time24Match[1].padStart(2, "0")}:${time24Match[2]}`;
  }

  return null;
}

/**
 * Identifies assignee from the known family members list or context
 */
export function parseAssignee(text, availableMembers = ["Priya", "Sarah", "David", "Alex"]) {
  if (!text) return null;
  const lower = text.toLowerCase();

  for (const member of availableMembers) {
    const memName = typeof member === "string" ? member : member.name;
    const regex = new RegExp(`\\b${memName}\\b`, "i");
    if (regex.test(lower)) {
      return memName;
    }
  }
  return null;
}

/**
 * Identifies priority from text
 */
export function parsePriority(text) {
  if (!text) return "Medium";
  const lower = text.toLowerCase();
  if (
    lower.includes("urgent") ||
    lower.includes("high priority") ||
    lower.includes("critical") ||
    lower.includes("asap")
  ) {
    return "High";
  }
  if (lower.includes("low priority") || lower.includes("when possible") || lower.includes("flexible")) {
    return "Low";
  }
  return "Medium";
}

/**
 * Checks if input is attempting to update/modify an existing task
 */
export function isUpdateRequest(text) {
  if (!text) return false;
  const lower = text.toLowerCase();

  const updateVerbs = [
    "change",
    "update",
    "modify",
    "reschedule",
    "reassign",
    "move",
    "postpone",
    "shift",
    "delay",
    "mark as",
    "mark completed",
    "mark complete",
    "mark done",
    "complete task",
    "reopen",
    "set priority",
    "switch to",
    "give it to",
    "assign it to"
  ];

  for (const verb of updateVerbs) {
    if (lower.includes(verb)) return true;
  }

  // Mention of an explicit task ID like "task-101", "task 101", "TASK-102"
  if (/\b(?:task[- ]?\d+)\b/i.test(text)) return true;

  return false;
}

/**
 * Scores how closely an existing task matches the user's change request
 */
export function scoreTaskMatch(task, input, context = {}) {
  const lowerInput = input.toLowerCase();
  let score = 0;

  // 1. Direct Stable ID Match (Highest weight: 100)
  const idRegex = new RegExp(`\\b${task.id}\\b`, "i");
  const numMatch = task.id.match(/\d+/);
  const bareNumRegex = numMatch ? new RegExp(`\\btask[ -]?${numMatch[0]}\\b`, "i") : null;

  if (idRegex.test(lowerInput) || (bareNumRegex && bareNumRegex.test(lowerInput))) {
    score += 100;
  }

  // 2. Conversation Context / Pronoun reference ("it", "that task", "this task")
  const hasPronoun = /\b(it|that task|this task|the task)\b/i.test(lowerInput);
  if (hasPronoun && context.lastFocusedTaskId === task.id) {
    score += 65;
  }

  // 3. Person / Assignee match
  // e.g. "David's task", "task for David", "Priya's wheelchair transport"
  const assigneeLower = (task.assignee || "").toLowerCase();
  if (assigneeLower && lowerInput.includes(assigneeLower)) {
    // If it's a possessive reference like "david's", give higher score
    if (lowerInput.includes(`${assigneeLower}'s`) || lowerInput.includes(`for ${assigneeLower}`)) {
      score += 35;
    } else {
      score += 20;
    }
  }

  // 4. Title / Topic keywords
  const titleWords = task.title
    .toLowerCase()
    .replace(/[^\w\s]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length > 3 && !["with", "from", "that", "this", "care", "prep"].includes(w));

  let matchedWords = 0;
  for (const word of titleWords) {
    if (lowerInput.includes(word)) {
      matchedWords++;
      score += 18;
    }
  }

  // High-value domain keywords
  const keywordMappings = [
    { key: "wheelchair", target: "wheelchair" },
    { key: "transport", target: "transport" },
    { key: "medication", target: "lisinopril" },
    { key: "prescription", target: "lisinopril" },
    { key: "blood pressure", target: "blood pressure" },
    { key: "bp", target: "blood pressure" },
    { key: "meal", target: "meal boxes" },
    { key: "echo", target: "echo show" }
  ];

  for (const km of keywordMappings) {
    if (lowerInput.includes(km.key) && task.title.toLowerCase().includes(km.target)) {
      score += 30;
    }
  }

  // 5. Date match (e.g. "today's task", "tomorrow's task")
  const taskDate = task.dueDate;
  const todayStr = new Date().toISOString().split("T")[0];
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toISOString().split("T")[0];

  if (lowerInput.includes("today") && taskDate === todayStr) score += 15;
  if (lowerInput.includes("tomorrow") && taskDate === tomorrowStr) score += 15;

  return score;
}

/**
 * Extracts proposed changes for a targeted task
 */
export function extractProposedChanges(targetTask, input, availableMembers) {
  const lower = input.toLowerCase();
  const changes = [];

  // Check priority update
  if (lower.includes("priority") || lower.includes("urgent") || lower.includes("routine")) {
    const newPriority = parsePriority(input);
    if (newPriority && newPriority !== targetTask.priority) {
      changes.push({
        field: "priority",
        fieldName: "Priority Level",
        originalValue: targetTask.priority,
        proposedValue: newPriority
      });
    }
  }

  // Check assignee update
  // Look for: "reassign to Priya", "assign to Sarah", "switch to David", "give it to Alex"
  const reassignMatch = input.match(/\b(?:reassign|assign|switch|give(?: it)?)\s+(?:to\s+)?([A-Za-z]+)\b/i);
  if (reassignMatch) {
    const targetName = reassignMatch[1];
    const matchedMember = parseAssignee(targetName, availableMembers);
    if (matchedMember && matchedMember !== targetTask.assignee) {
      changes.push({
        field: "assignee",
        fieldName: "Assignee",
        originalValue: targetTask.assignee,
        proposedValue: matchedMember
      });
    }
  }

  // Check due time update
  // e.g. "to 6 PM", "at 6 PM", "reschedule to 18:00"
  const hasTimeIndicator = lower.includes(" pm") || lower.includes(" am") || lower.includes("noon") || /\b\d{1,2}:\d{2}\b/.test(input);
  if (hasTimeIndicator) {
    const newTime = parseTime(input);
    if (newTime && newTime !== targetTask.dueTime) {
      changes.push({
        field: "dueTime",
        fieldName: "Due Time",
        originalValue: targetTask.dueTime || "Not Set",
        proposedValue: newTime
      });
    }
  }

  // Check due date update
  // e.g. "postpone to tomorrow", "move to Friday", "reschedule to 2026-10-25"
  if (lower.includes("tomorrow") || lower.includes("today") || lower.includes("monday") || lower.includes("friday") || lower.includes("postpone") || lower.includes("reschedule")) {
    const newDate = parseDate(input);
    if (newDate && newDate !== targetTask.dueDate) {
      changes.push({
        field: "dueDate",
        fieldName: "Due Date",
        originalValue: targetTask.dueDate,
        proposedValue: newDate
      });
    }
  }

  // Check status update (complete / reopen)
  if (lower.includes("mark as completed") || lower.includes("mark complete") || lower.includes("complete task") || lower.includes("mark done")) {
    if (targetTask.status !== "Completed") {
      changes.push({
        field: "status",
        fieldName: "Status",
        originalValue: targetTask.status,
        proposedValue: "Completed"
      });
    }
  } else if (lower.includes("reopen") || lower.includes("mark pending") || lower.includes("uncomplete")) {
    if (targetTask.status !== "Pending") {
      changes.push({
        field: "status",
        fieldName: "Status",
        originalValue: targetTask.status,
        proposedValue: "Pending"
      });
    }
  }

  return changes;
}

/**
 * Main parser entry point
 * Accepts prompt, members, existing tasks, and conversation context.
 */
export function parseAssistantRequest(
  rawInput,
  availableMembers = ["Priya", "Sarah", "David", "Alex"],
  existingTasks = [],
  conversationContext = {}
) {
  if (!rawInput || typeof rawInput !== "string" || !rawInput.trim()) {
    return {
      status: "error",
      engine: "local_demo_heuristic",
      engineNotice: LOCAL_ENGINE_NOTICE,
      message:
        "Please enter or speak a caregiving instruction. For example: 'Create a reminder for Dad's appointment tomorrow at 5 PM and assign arranging transport to Priya.'"
    };
  }

  const input = rawInput.trim();
  const lower = input.toLowerCase();

  // =========================================================================
  // STEP 1: Handle Ongoing Disambiguation Resolution
  // =========================================================================
  if (conversationContext.pendingDisambiguation) {
    const { candidates, pendingChanges } = conversationContext.pendingDisambiguation;

    // Check if user selected one of the candidates by ID or name
    let selectedTask = null;
    for (const c of candidates) {
      if (
        lower.includes(c.id.toLowerCase()) ||
        lower.includes(c.title.toLowerCase().slice(0, 15)) ||
        (c.assignee && lower.includes(c.assignee.toLowerCase()))
      ) {
        selectedTask = c;
        break;
      }
    }

    // Number matching e.g. "first one", "1", "option 2"
    if (!selectedTask) {
      if (lower.includes("first") || lower === "1" || lower.includes("option 1")) {
        selectedTask = candidates[0];
      } else if (lower.includes("second") || lower === "2" || lower.includes("option 2")) {
        selectedTask = candidates[1];
      }
    }

    if (selectedTask) {
      // Re-extract changes or use pending changes
      const changes = pendingChanges || extractProposedChanges(selectedTask, input, availableMembers);
      return {
        status: "ready_to_update",
        engine: "local_demo_heuristic",
        engineNotice: LOCAL_ENGINE_NOTICE,
        originalInput: input,
        targetTask: selectedTask,
        changes,
        summary: `Identified ${selectedTask.id}: "${selectedTask.title}". Please review the proposed changes before saving.`,
        alexaVoiceSpeech: `I've prepared the update for task ${selectedTask.id}. Please confirm to apply.`
      };
    }
  }

  // =========================================================================
  // STEP 2: Contextual Task Update / Modification
  // =========================================================================
  if (isUpdateRequest(input) && existingTasks && existingTasks.length > 0) {
    // Score all existing tasks
    const scoredTasks = existingTasks
      .map((t) => ({
        task: t,
        score: scoreTaskMatch(t, input, conversationContext)
      }))
      .sort((a, b) => b.score - a.score);

    const topMatch = scoredTasks[0];
    const secondMatch = scoredTasks[1];

    // Check if multiple tasks have high, competing scores (Ambiguity!)
    const highMatches = scoredTasks.filter((m) => m.score >= 35);

    if (highMatches.length > 1 && topMatch.score - secondMatch.score < 25) {
      // Multiple tasks match -> ask for clarification!
      const candidates = highMatches.slice(0, 3).map((m) => m.task);
      const pendingChanges = extractProposedChanges(candidates[0], input, availableMembers);

      return {
        status: "disambiguation_needed",
        engine: "local_demo_heuristic",
        engineNotice: LOCAL_ENGINE_NOTICE,
        originalInput: input,
        question: `I found ${candidates.length} tasks matching your request. Which one did you mean?`,
        candidates,
        pendingChanges,
        suggestions: candidates.map((c) => `${c.id}: ${c.title}`),
        alexaVoiceSpeech: `I found ${candidates.length} matching tasks. Which one would you like to update?`
      };
    }

    // Single confident match (score >= 30)
    if (topMatch && topMatch.score >= 30) {
      const targetTask = topMatch.task;
      const changes = extractProposedChanges(targetTask, input, availableMembers);

      if (changes.length === 0) {
        return {
          status: "no_changes_needed",
          engine: "local_demo_heuristic",
          engineNotice: LOCAL_ENGINE_NOTICE,
          originalInput: input,
          targetTask,
          message: `Task ${targetTask.id} ("${targetTask.title}") already reflects those details. No updates are required.`,
          alexaVoiceSpeech: `Task ${targetTask.id} already has those values.`
        };
      }

      return {
        status: "ready_to_update",
        engine: "local_demo_heuristic",
        engineNotice: LOCAL_ENGINE_NOTICE,
        originalInput: input,
        targetTask,
        changes,
        summary: `Proposed update for ${targetTask.id} ("${targetTask.title}"): ${changes
          .map((c) => `${c.fieldName} (${c.originalValue} ➡️ ${c.proposedValue})`)
          .join(", ")}.`,
        alexaVoiceSpeech: `I've prepared the update for task ${targetTask.id}. Please review the before-and-after values and confirm to apply.`
      };
    }
  }

  // =========================================================================
  // STEP 3: Task & Appointment Creation
  // =========================================================================
  const detectedDate = parseDate(input);
  const detectedTime = parseTime(input);
  const detectedAssignee = parseAssignee(input, availableMembers);
  const detectedPriority = parsePriority(input);

  const isAppointmentReminder =
    lower.includes("appointment") ||
    lower.includes("doctor") ||
    lower.includes("checkup") ||
    lower.includes("clinic") ||
    lower.includes("therapy") ||
    lower.includes("hospital");

  const hasTransportAssignment =
    lower.includes("transport") ||
    lower.includes("ride") ||
    lower.includes("drive") ||
    lower.includes("pickup") ||
    lower.includes("pick up");

  const isReminderIntent = lower.includes("reminder") || lower.includes("remind");

  // CASE 3A: Dual intent: Appointment + Transport Task assignment
  if (isAppointmentReminder && (hasTransportAssignment || detectedAssignee)) {
    if (!detectedDate && !detectedTime) {
      return {
        status: "needs_clarification",
        engine: "local_demo_heuristic",
        engineNotice: LOCAL_ENGINE_NOTICE,
        originalInput: input,
        clarificationType: "timing",
        question: "I see you'd like to schedule Dad's appointment, but what date and time is it for?",
        suggestions: ["Tomorrow at 5:00 PM", "Friday at 10:00 AM", "Next Monday at 2:00 PM"],
        partialData: {
          assignee: detectedAssignee || "Priya",
          hasTransport: hasTransportAssignment
        }
      };
    }

    const aptDate = detectedDate || new Date().toISOString().split("T")[0];
    const aptTime = detectedTime || "17:00";
    const assignee = detectedAssignee || "Priya";

    let aptTitle = "Dad's Medical Appointment";
    if (lower.includes("cardiology")) aptTitle = "Dad's Cardiology Appointment";
    else if (lower.includes("therapy")) aptTitle = "Dad's Physical Therapy Appointment";
    else if (lower.includes("checkup")) aptTitle = "Dad's Health Checkup";

    let transportTime = "16:00";
    if (aptTime) {
      const [h, m] = aptTime.split(":").map(Number);
      const prepHour = Math.max(0, h - 1);
      transportTime = `${String(prepHour).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
    }

    const proposedAppointment = {
      id: `apt-${Date.now()}`,
      title: aptTitle,
      recipient: "Dad (Robert Jenkins)",
      doctor: "Dr. Robert Henderson",
      date: aptDate,
      time: aptTime,
      location: "St. Jude Medical Pavilion",
      notes: "Follow-up consultation. Transport coordinated within CareCircle.",
      reminderSet: true,
      reminderNotice: "1 day before & 2 hours before",
      transportAssignedTo: assignee,
      status: "Upcoming"
    };

    const newTaskId = generateStableTaskId(existingTasks);
    const proposedTask = {
      id: newTaskId,
      title: `Arrange transport for ${aptTitle}`,
      description: `Coordinate accessible ride and accompany Dad for appointment on ${aptDate} at ${aptTime}.`,
      dueDate: aptDate,
      dueTime: transportTime,
      priority: "High",
      status: "Pending",
      assignee: assignee,
      category: "Transport"
    };

    return {
      status: "ready_to_confirm",
      engine: "local_demo_heuristic",
      engineNotice: LOCAL_ENGINE_NOTICE,
      originalInput: input,
      summary: `I've prepared a calendar appointment for Dad with reminders, plus a coordinated transport task (${newTaskId}) assigned to ${assignee}.`,
      items: [
        { type: "appointment", data: proposedAppointment },
        { type: "task", data: proposedTask }
      ],
      alexaVoiceSpeech: `I've prepared a reminder for Dad's appointment on ${aptDate} at ${aptTime}, and assigned arranging transport to ${assignee}. Please confirm to save this to your CareCircle.`
    };
  }

  // CASE 3B: Appointment only
  if (isAppointmentReminder) {
    if (!detectedDate && !detectedTime) {
      return {
        status: "needs_clarification",
        engine: "local_demo_heuristic",
        engineNotice: LOCAL_ENGINE_NOTICE,
        originalInput: input,
        clarificationType: "timing",
        question: "When is this appointment scheduled? Please specify the date and time.",
        suggestions: ["Tomorrow at 5:00 PM", "Friday at 11:00 AM", "Next Tuesday at 3:30 PM"],
        partialData: {}
      };
    }

    const aptDate = detectedDate || new Date().toISOString().split("T")[0];
    const aptTime = detectedTime || "10:00";

    const proposedAppointment = {
      id: `apt-${Date.now()}`,
      title: "Dad's Healthcare Appointment",
      recipient: "Dad (Robert Jenkins)",
      doctor: "Primary Care Clinic",
      date: aptDate,
      time: aptTime,
      location: "Local Medical Office",
      notes: "Created via CareCircle assistant.",
      reminderSet: true,
      reminderNotice: "2 hours before",
      transportAssignedTo: detectedAssignee || "Family Caregiver",
      status: "Upcoming"
    };

    return {
      status: "ready_to_confirm",
      engine: "local_demo_heuristic",
      engineNotice: LOCAL_ENGINE_NOTICE,
      originalInput: input,
      summary: `I've set up an appointment and reminder for Dad on ${aptDate} at ${aptTime}.`,
      items: [{ type: "appointment", data: proposedAppointment }],
      alexaVoiceSpeech: `I prepared an appointment for Dad on ${aptDate} at ${aptTime}. Would you like me to save it?`
    };
  }

  // CASE 3C: General Care Task or Reminder
  if (
    isReminderIntent ||
    lower.includes("task") ||
    lower.includes("pick up") ||
    lower.includes("refill") ||
    lower.includes("buy") ||
    lower.includes("prep")
  ) {
    if (!detectedDate && !detectedAssignee) {
      return {
        status: "needs_clarification",
        engine: "local_demo_heuristic",
        engineNotice: LOCAL_ENGINE_NOTICE,
        originalInput: input,
        clarificationType: "assignee_and_time",
        question: "Who in the family should handle this task, and when is it due?",
        suggestions: ["Assign to Priya for Tomorrow", "Assign to David for Today", "Assign to Sarah for Friday"],
        partialData: {
          tentativeTitle: input
        }
      };
    }

    if (!detectedDate) {
      return {
        status: "needs_clarification",
        engine: "local_demo_heuristic",
        engineNotice: LOCAL_ENGINE_NOTICE,
        originalInput: input,
        clarificationType: "date_missing",
        question: `When should ${detectedAssignee || "the caregiver"} complete this?`,
        suggestions: ["Today at 5:00 PM", "Tomorrow at 10:00 AM", "This Friday"],
        partialData: {
          assignee: detectedAssignee
        }
      };
    }

    const taskDate = detectedDate;
    const taskTime = detectedTime || "12:00";
    const assignee = detectedAssignee || "Priya";

    let taskTitle = input
      .replace(/create a (reminder|task) (for|to)/i, "")
      .replace(/remind \w+ to/i, "")
      .replace(/by \w+ at \w+(?:\s*(am|pm))?/i, "")
      .replace(/with (high|low|medium) priority/i, "")
      .trim();
    if (taskTitle.length < 3) taskTitle = input;
    taskTitle = taskTitle.charAt(0).toUpperCase() + taskTitle.slice(1);

    const newTaskId = generateStableTaskId(existingTasks);
    const proposedTask = {
      id: newTaskId,
      title: taskTitle,
      description: `Task logged via CareCircle Assistant: "${input}".`,
      dueDate: taskDate,
      dueTime: taskTime,
      priority: detectedPriority,
      status: "Pending",
      assignee: assignee,
      category: lower.includes("medication") || lower.includes("refill") ? "Medical" : "Home Care"
    };

    return {
      status: "ready_to_confirm",
      engine: "local_demo_heuristic",
      engineNotice: LOCAL_ENGINE_NOTICE,
      originalInput: input,
      summary: `I've prepared a new task "${taskTitle}" (${newTaskId}) assigned to ${assignee} due ${taskDate} at ${taskTime}.`,
      items: [{ type: "task", data: proposedTask }],
      alexaVoiceSpeech: `I've created a task for ${assignee} due on ${taskDate} with ${detectedPriority} priority. Please confirm to save.`
    };
  }

  // Fallback for vague inputs
  return {
    status: "needs_clarification",
    engine: "local_demo_heuristic",
    engineNotice: LOCAL_ENGINE_NOTICE,
    originalInput: input,
    clarificationType: "general",
    question:
      "I couldn't quite determine if this is an appointment or a care task. Could you specify details like date, time, and assignee?",
    suggestions: [
      "Create a reminder for Dad's appointment tomorrow at 5 PM and assign arranging transport to Priya.",
      "Remind David to refill Dad's heart medication by Friday at 10 AM",
      "Schedule physical therapy session for Dad next Monday at 2 PM",
      "Reschedule TASK-102 to 6 PM"
    ]
  };
}
